//! The Rust reader reaches every verdict in `corpus/seal-cases.json`, the file the independent
//! reference reader (`corpus/reference_reader/run.py`, the `reference-reader` flake check) and
//! `tessera-wasm` check too. All readers held to one file of verdicts agree by construction (#573,
//! SPEC §4, ADR-0066).
//!
//! Each case is a stored pair, `(manifest.json bytes, manifest.seal)`, the way a container holds
//! them (`seal` is `null` for a product without the seal member). The file is generated by
//! `corpus/reference_reader/make_seal_cases.py` from the 8 corpus products in the ADR-0066 layout;
//! see its `about` for the case families: each product as stored, with a newer-format field sealed
//! (verifies), with a field spliced in under the old seal (tampered), respelled under its old seal or
//! by the attacker (T4–T7, S7 = #901's sealed `64.0`, S8: refused as non-canonical), with an exact
//! double beyond 2^53 (S5b: refused by I-JSON), in the alpha layout (refused, no migration) and with
//! its seal in band (refused); plus, on `recon_int16`, the typed-layer and I-JSON cases (duplicate
//! keys, NaN, lone surrogate, nesting, integers beyond ±(2^53−1) in any spelling, records as arrays,
//! a declared field of another JSON type, an unsupported major version, a block listed twice, a block
//! without a digest, a malformed seal member), and the derived-block cases of ADR-0028 §4 (#720: a
//! derived block added or regenerated verifies with `content_hash` unchanged, one counted in
//! `content_hash` or a primary block marked derived under the old root is tampered, an all-derived
//! product has the empty root, and a `class` other than `"derived"` is refused).

use serde_json::Value;
use tessera_core::{Error, Manifest};

/// The number of cases the generator writes: a lost or gained case is a visible change here.
const CASES: usize = 164;

fn cases() -> Vec<Value> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../corpus/seal-cases.json");
    let text = std::fs::read_to_string(path).expect("corpus/seal-cases.json present");
    let doc: Value = serde_json::from_str(&text).expect("seal-cases.json parses");
    doc["cases"].as_array().expect("cases array").clone()
}

/// A case's `manifest.json` bytes: the UTF-8 string they spell (`manifest`), or `manifest_hex` for
/// bytes no JSON string holds (invalid UTF-8).
fn manifest_bytes(c: &Value) -> Vec<u8> {
    match c["manifest_hex"].as_str() {
        Some(hex) => (0..hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("manifest_hex is hex"))
            .collect(),
        None => c["manifest"].as_str().unwrap().as_bytes().to_vec(),
    }
}

/// A case's stored members: the manifest bytes and the seal member (`None` when absent).
fn members(c: &Value) -> (Vec<u8>, Option<Vec<u8>>) {
    let bytes = manifest_bytes(c);
    let seal = c["seal"].as_str().map(|s| s.as_bytes().to_vec());
    (bytes, seal)
}

fn read(c: &Value) -> tessera_core::Result<Manifest> {
    let (bytes, seal) = members(c);
    Manifest::from_stored_members(&bytes, seal.as_deref())
}

/// The verdict the Rust reader reaches, in the file's vocabulary, plus the view's newer fields.
/// `tampered` is an integrity failure (the seal, `id` or `content_hash` doesn't match); `refused`
/// is everything a reader does not read at all.
fn rust_verdict(c: &Value) -> (&'static str, Vec<String>) {
    match read(c) {
        Ok(m) => ("ok", m.newer_fields().to_vec()),
        Err(Error::Integrity { .. }) => ("tampered", Vec::new()),
        // The layout: no seal member (the alpha layout, rule 10), a malformed one, or the seal in
        // band (rule 3).
        Err(
            Error::UnsupportedLayout { .. }
            | Error::MalformedSeal { .. }
            | Error::InBandSeal { .. },
        ) => ("refused", Vec::new()),
        // Not the one spelling of the value (rule 4): key order, whitespace, escapes, `64.0`.
        Err(Error::NonCanonical { .. }) => ("refused", Vec::new()),
        // Not I-JSON (duplicate key, NaN, lone surrogate, nesting) or another declared form.
        Err(Error::Serde(_)) => ("refused", Vec::new()),
        // Not I-JSON: an integer beyond ±(2^53−1), which JCS can't seal exactly (SPEC §1, #886).
        Err(Error::InexactInteger { .. }) => ("refused", Vec::new()),
        Err(Error::UnsupportedVersion(_)) => ("refused", Vec::new()),
        // A block name listed twice (SPEC §5, #734), refused before any hash of the typed layer.
        Err(Error::DuplicateBlockName { .. }) => ("refused", Vec::new()),
        // A block without a digest (SPEC §5: a sealed product's blocks carry one).
        Err(Error::MissingDigest(_)) => ("refused", Vec::new()),
        Err(e) => panic!("unexpected error class: {e}"),
    }
}

#[test]
fn rust_reader_reaches_every_seal_case_verdict() {
    let cases = cases();
    assert_eq!(cases.len(), CASES, "seal-cases.json lost or gained cases");
    let mut disagreements = Vec::new();
    for c in &cases {
        let name = c["name"].as_str().unwrap();
        let (verdict, newer) = rust_verdict(c);
        let want_newer: Vec<String> =
            serde_json::from_value(c["newer_fields"].clone()).expect("newer_fields list");
        if verdict != c["verdict"].as_str().unwrap() || newer != want_newer {
            disagreements.push(format!(
                "{name}: expected {} {want_newer:?}, got {verdict} {newer:?}",
                c["verdict"]
            ));
        }
    }
    assert!(disagreements.is_empty(), "{disagreements:#?}");
}

/// Every case family is present for each corpus product, by name, so the gate can't pass on a
/// file that lost one (a vacuous pass over fewer cases).
#[test]
fn every_corpus_product_has_every_case_family() {
    let cases = cases();
    let names: Vec<&str> = cases.iter().map(|c| c["name"].as_str().unwrap()).collect();
    let corpus: Vec<&str> = names
        .iter()
        .filter_map(|n| n.strip_suffix("/as-stored"))
        .collect();
    assert_eq!(corpus.len(), 8, "one as-stored case per corpus file");
    let mut shaped = 0;
    for base in &corpus {
        for suffix in [
            "newer-field-resealed",
            "field-spliced",
            "t4-keys-reordered",
            "t5-whitespace",
            "t6-unicode-escape",
            "s5b-exact-double-beyond-2^53-resealed",
            "s8-pretty-resealed",
            "alpha-layout",
            "seal-in-band-resealed",
        ] {
            let want = format!("{base}/{suffix}");
            assert!(names.contains(&want.as_str()), "missing case {want}");
        }
        // T7/S7 apply to the products with an array block (a `shape`).
        let t7 = format!("{base}/t7-shape-as-float");
        let s7 = format!("{base}/s7-shape-as-float-resealed");
        assert_eq!(names.contains(&t7.as_str()), names.contains(&s7.as_str()));
        shaped += usize::from(names.contains(&s7.as_str()));
    }
    // The spike's count over the corpus files with an array block.
    assert_eq!(
        shaped, 5,
        "T7/S7 on every corpus product with an array shape"
    );
}

fn case(name: &str) -> Value {
    cases()
        .into_iter()
        .find(|c| c["name"] == name)
        .unwrap_or_else(|| panic!("no case {name}"))
}

/// #901: a sealed `64.0` in an integer field (an array `shape`) is refused as non-canonical at the
/// byte comparison, naming the offset of the `.`, before any typed layer could read it differently.
#[test]
fn s7_a_sealed_float_spelling_of_an_integer_is_refused_as_non_canonical() {
    let mut seen = 0;
    for c in cases() {
        let name = c["name"].as_str().unwrap();
        if !name.ends_with("/s7-shape-as-float-resealed") {
            continue;
        }
        seen += 1;
        let text = c["manifest"].as_str().unwrap();
        // The seal is the attacker's own, over these very bytes.
        let digest = tessera_core::hash::digest(text.as_bytes());
        assert_eq!(c["seal"].as_str(), Some(digest.as_str()), "{name}");
        let dot = text.find(".0").unwrap();
        match read(&c) {
            Err(Error::NonCanonical { offset, .. }) => assert_eq!(offset, dot, "{name}"),
            other => panic!("{name}: expected NonCanonical, got {other:?}"),
        }
    }
    assert_eq!(seen, 5);
}

/// S5b is refused by the strict parse's I-JSON check, not the byte comparison: the case's bytes
/// are their own JCS form, which a reader that only compares bytes would accept (#933 item 2).
#[test]
fn s5b_is_refused_by_i_json_on_bytes_that_are_their_own_jcs_form() {
    for c in cases() {
        let name = c["name"].as_str().unwrap();
        if !name.ends_with("/s5b-exact-double-beyond-2^53-resealed") {
            continue;
        }
        let text = c["manifest"].as_str().unwrap();
        let reparsed: Value = serde_json::from_str(text).unwrap();
        assert_eq!(
            serde_jcs::to_vec(&reparsed).unwrap(),
            text.as_bytes(),
            "{name}"
        );
        match read(&c) {
            Err(Error::InexactInteger { path, .. }) => {
                assert_eq!(path, "metadata.daq_start_ns", "{name}")
            }
            other => panic!("{name}: expected InexactInteger, got {other:?}"),
        }
    }
}

/// The alpha layout (no seal member) is refused naming the declared version and both formats.
#[test]
fn the_alpha_layout_cases_name_both_formats() {
    for c in cases() {
        let name = c["name"].as_str().unwrap();
        if !name.ends_with("/alpha-layout") {
            continue;
        }
        let e = read(&c).unwrap_err();
        let Error::UnsupportedLayout { found, required } = &e else {
            panic!("{name}: expected UnsupportedLayout, got {e:?}")
        };
        for needle in [
            "tessera_version \"0.0.0\"",
            "no `manifest.seal`",
            "in-band `manifest_hash`",
            "not stored as its JCS bytes",
        ] {
            assert!(found.contains(needle), "{name}: {needle} in {found}");
        }
        assert!(required.contains("manifest.seal"), "{name}: {required}");
    }
}

/// A view with newer fields can be read and verified, but nothing re-seals or re-stores it: the
/// struct doesn't carry the fields, so either would drop sealed content (ADR-0060 §2.2).
#[test]
fn a_view_with_newer_fields_is_never_resealed_or_reemitted() {
    let m = read(&case("recon_int16/newer-field-resealed")).unwrap();
    assert_eq!(m.newer_fields(), ["actors"]);
    let refused = |r: tessera_core::Result<()>| {
        assert!(
            matches!(r, Err(Error::NewerFormatFields { ref fields }) if fields == &["actors"]),
            "{r:?}"
        )
    };
    refused(tessera_core::ProductBuilder::from_manifest(&m).map(drop));
    refused(m.compute_manifest_hash().map(drop));
    refused(m.to_stored().map(drop));
    // The struct check names the real reason instead of crying tampering.
    refused(m.verify());
}

/// A view of an encoding the struct normalises still verifies as bytes, but is not re-stored as
/// its own JSON, which would no longer carry the seal.
#[test]
fn a_normalised_view_is_not_reemitted_under_its_seal() {
    for name in [
        "recon_int16/study-null-resealed",
        "recon_int16/sources-omitted-resealed",
    ] {
        let m = read(&case(name)).unwrap();
        assert!(m.newer_fields().is_empty(), "{name}");
        let err = m.to_stored().unwrap_err();
        assert!(matches!(err, Error::Integrity { .. }), "{name}: {err}");
    }
}

/// The seal a writer stores is `blake3` over the bytes it stores, for every corpus product: the
/// stored pair reads back, and `to_stored` reproduces it byte for byte.
#[test]
fn the_writer_stores_the_bytes_its_seal_is_over() {
    for c in cases() {
        let name = c["name"].as_str().unwrap();
        if !name.ends_with("/as-stored") {
            continue;
        }
        let m = read(&c).unwrap();
        let (bytes, seal) = m.to_stored().unwrap();
        assert_eq!(bytes, c["manifest"].as_str().unwrap().as_bytes(), "{name}");
        assert_eq!(Some(seal.as_str()), c["seal"].as_str(), "{name}");
    }
}

#[test]
fn parse_strict_refuses_trailing_input() {
    assert!(tessera_core::canonical::parse_strict(r#"{"a":1} {"a":2}"#).is_err());
}

/// The duplicate-key cases are refused for being duplicates, at the top level, nested, and after
/// unescaping: not by some other parse error that would hide a regression in the check.
#[test]
fn duplicate_keys_are_refused_by_name() {
    for name in [
        "recon_int16/duplicate-top-level-key",
        "recon_int16/duplicate-key-after-unescaping",
        "recon_int16/duplicate-nested-key",
    ] {
        let err = read(&case(name)).unwrap_err();
        assert!(
            matches!(&err, Error::Serde(e) if e.to_string().contains("duplicate key")),
            "{name}: {err}"
        );
    }
}

/// The lone-surrogate case is refused by the strict parse, not by some later check: `serde_json`
/// refuses `\ud800` not followed by a low-surrogate escape (it reads the escape as unfinished).
#[test]
fn a_lone_surrogate_is_refused_by_the_parser() {
    let err = read(&case("recon_int16/lone-surrogate")).unwrap_err();
    assert!(
        matches!(&err, Error::Serde(e) if e.to_string().contains("hex escape")),
        "{err}"
    );
}

/// The integer cases are refused for the integer, not by some other check that would hide a
/// regression in it: each names the value's path. Without the rule, the first two verify `ok`, the
/// second under the seal of a different value (#886).
#[test]
fn integers_beyond_2_pow_53_are_refused_by_path() {
    for (name, want) in [
        ("integer-2^53-plus-1-resealed", "metadata.daq_start_ns"),
        (
            "integer-2^53-plus-1-served-as-2^53",
            "metadata.daq_start_ns",
        ),
        ("integer-below-minus-2^53-resealed", "metadata.daq_start_ns"),
        (
            "integer-with-zero-fraction-above-2^53-resealed",
            "metadata.daq_start_ns",
        ),
        (
            "integer-with-exponent-above-2^53-resealed",
            "metadata.daq_start_ns",
        ),
        ("integer-1e300-resealed", "metadata.daq_start_ns"),
        ("integer-epoch-ns-resealed", "metadata.daq_start_ns"),
        ("fraction-lost-above-2^53-resealed", "metadata.daq_start_ns"),
        (
            "fraction-rounding-to-2^53-resealed",
            "metadata.daq_start_ns",
        ),
        (
            "integer-above-2^53-in-generation-config-resealed",
            "generation.config.seed",
        ),
    ] {
        let err = read(&case(&format!("recon_int16/{name}"))).unwrap_err();
        assert!(
            matches!(&err, Error::InexactInteger { path, .. } if path == want),
            "{name}: {err}"
        );
    }
}

/// Bytes a string API would change before the seal check (a default `TextDecoder` drops a leading
/// byte-order mark and maps invalid UTF-8 to U+FFFD) are refused by the strict parse, whatever the
/// seal: the seal is over the stored bytes, never over text decoded from them. The U+FFFD
/// spelling itself verifies, so the refusal is about the bytes.
#[test]
fn bytes_a_text_decoder_would_change_are_refused_by_the_strict_parse() {
    for name in [
        "byte-order-mark",
        "byte-order-mark-resealed",
        "invalid-utf8-resealed",
        "invalid-utf8-under-the-seal-of-its-replacement",
    ] {
        let c = case(&format!("recon_int16/{name}"));
        let err = read(&c).unwrap_err();
        assert!(matches!(err, Error::Serde(_)), "{name}: {err}");
    }
    assert!(read(&case("recon_int16/replacement-character-resealed")).is_ok());
}
